  const ids = new Map();
  for(const [key,value] of Object.entries(globalThis.dexLocales.en)) {
    if(!ids.has(value))ids.set(value,[]);
    ids.get(value).push(key);
  }
  for(const [column,language] of ['ja','fr','it','de','es'].entries()) {
    const dictionary = {};
    for(const [source,...translations] of rows) {
      if(!ids.has(source))throw new Error('Unknown interface source: '+source);
      for(const key of ids.get(source))dictionary[key]=translations[column];
    }
    globalThis.dexLocales[language]=dictionary;
  }
  const remaining={
    ja:['残り{count}件のタスク','残り{count}件のタスク'],
    fr:['{count} tâche restante','{count} tâches restantes'],
    it:['{count} attività rimanente','{count} attività rimanenti'],
    de:['{count} Aufgabe verbleibend','{count} Aufgaben verbleibend'],
    es:['Queda {count} tarea','Quedan {count} tareas']
  };
  for(const [language,[one,other]] of Object.entries(remaining)) {
    const dictionary=globalThis.dexLocales[language];
    dictionary['route.remaining.one']=one;
    dictionary['route.remaining.other']=other;
    dictionary['route.remaining.many']=other;
  }
